function productCard(p){
 const fav=nextFavorites.has(p.id),qty=nextQuantities[p.id]||1;
 const price=p.price===null?'<strong class="product-price product-price--query">Цена по запросу</strong>':'<strong class="product-price">'+fmt(p.price)+'</strong><small class="product-unit">за 1 шт.</small>';
 const quantity=p.stock>0?'<div class="product-quantity"><span>Количество</span><div class="quantity-stepper"><button type="button" data-action="qty-down" data-product-id="'+p.id+'" aria-label="Уменьшить количество '+p.brand+' '+p.model+'">−</button><output data-quantity="'+p.id+'">'+qty+'</output><button type="button" data-action="qty-up" data-product-id="'+p.id+'" aria-label="Увеличить количество '+p.brand+' '+p.model+'">+</button></div></div>':'<span class="product-quantity-note">Количество уточнит специалист</span>';
 const purchase=p.stock>0?'<button type="button" class="button primary product-buy" data-action="product-add" data-product-id="'+p.id+'">'+(p.kind==='delivery'?'Запросить поставку':'В корзину')+'</button>':'<button type="button" class="button primary product-buy" disabled>Нет в наличии</button><button type="button" class="product-ask-link" data-action="product-question" data-product-id="'+p.id+'">Уточнить у сервиса</button>';
 return '<article class="next-product-card" data-kind="'+p.kind+'"><div class="product-card-head"><div class="product-art" aria-hidden="true">'+tireGraphic+'<span>'+p.season+'</span></div><div class="product-identity"><span class="product-brand">'+p.brand+'</span><h3>'+p.model+'</h3><p class="product-size">'+p.size+'</p><div class="product-tags">'+p.tags.map(t=>'<span>'+t+'</span>').join('')+'</div></div><button type="button" class="product-favorite'+(fav?' is-favorite':'')+'" data-action="product-favorite" data-product-id="'+p.id+'" aria-pressed="'+fav+'" aria-label="'+(fav?'Убрать из избранного: ':'В избранное: ')+p.brand+' '+p.model+'">'+heartGraphic+'</button></div><div class="product-card-info"><div class="product-price-block">'+price+'</div><span class="product-status product-status--'+p.kind+'">'+p.status+'</span><span class="product-delivery">'+p.delivery+'</span>'+quantity+'</div><div class="product-card-actions"><button type="button" class="button secondary product-details" data-action="product-details" data-product-id="'+p.id+'">Подробнее</button>'+purchase+'</div></article>';
}
