 return '<article class="next-work-card"><div class="work-card-head"><span class="work-card-icon">'+icons.car+'</span><time datetime="'+item.iso+'">'+item.date+'</time><span class="work-demo-tag">Демо-пример</span></div><div class="work-card-title"><div><h3>'+item.car+'</h3><p>Автомобиль · '+item.year+'</p></div><button type="button" class="work-view" data-action="work-details" data-work-id="'+item.id+'">Смотреть '+icons.arrow+'</button></div><ul class="next-work-list">'+item.items.map(row=>'<li><span>'+row[0]+'</span><b>'+fmt(row[1])+'</b></li>').join('')+'</ul><div class="next-work-total"><span>Работы'+(item.discount?' · скидка '+Math.round(item.discount/item.subtotal*100)+'%':'')+'</span><strong>'+fmt(item.total)+'</strong></div></article>';
