const customerNav=[['Главная','customer'],['Автомобиль','customer-car'],['История','customer-history'],['Записи','booking']];
function customerShell(){return `<div class="customer-app"><aside class="customer-side">${topBrand()}<div class="side-label">КАБИНЕТ КЛИЕНТА</div><nav>${customerNav.map(([label,key],i)=>`<button class="side-item ${customerTab===label?'selected':''}" data-customer-tab="${label}"><span>${[icons.home,icons.car,icons.history,icons.calendar][i]}</span>${label}</button>`).join('')}</nav><div class="side-help"><span class="help-icon">${icons.chat}</span><strong>Мы на связи</strong><p>Есть вопрос по обслуживанию?</p><button class="text-link" data-action="ask">Написать сервису ${icons.arrow}</button></div><div class="side-profile"><span class="avatar">АМ</span><span><b>Алексей М.</b><small>Личный кабинет</small></span><button class="more-button" aria-label="Дополнительно">···</button></div></aside><section class="customer-main"><header class="customer-top"><button class="mobile-brand-link" data-screen="next">${topBrand()}</button><span class="account-context">Личный кабинет</span><button class="profile-mini"><span class="avatar">АМ</span><span>Алексей</span><span>⌄</span></button></header><main class="customer-content">${customerTab==='Главная'?customerHome():customerTab==='Записи'?customerBookingCard():customerHistory()}</main><nav class="bottom-nav" aria-label="Основная навигация">${customerNav.map(([label],i)=>`<button class="bottom-item ${customerTab===label?'active':''}" data-customer-tab="${label}">${[icons.home,icons.car,icons.history,icons.calendar][i]}<span>${label==='Автомобиль'?'Авто':label}</span></button>`).join('')}</nav></section></div>`}
function customerHome(){return `${demo==='error'?stateNotice():''}<header class="customer-welcome"><div><div class="eyebrow">ПОНЕДЕЛЬНИК, 28 СЕНТЯБРЯ</div><h1>Здравствуйте, Алексей</h1><p>Что происходит с вашим автомобилем и что нужно сделать дальше.</p></div><button class="quiet-button desktop-only" data-screen="booking">Записи и управление ${icons.arrow}</button></header><section class="current-booking"><div class="booking-visual"><span class="booking-visual-label">ВАШ СЛЕДУЮЩИЙ ВИЗИТ</span><div class="calendar-art"><b>28</b><span>СЕН</span></div><div class="visual-decoration">${icons.car}</div></div><div class="booking-details"><div class="booking-title-line">${badge('Подтверждена','success')}<span class="small-muted">№ ЗП-2048</span></div><h2>Замена масла<br class="mobile-only"> и фильтров</h2><div class="booking-meta"><span>${icons.calendar} Понедельник, 28 сентября · 15:30</span><span>${icons.car} Toyota Camry · 2019</span><span>⌖ КОЛЕСОВИК · Центральный</span></div><div class="booking-footer"><span>Приезжайте за 10 минут до начала</span><button class="button secondary compact" data-screen="booking">Управлять записью ${icons.arrow}</button></div></div></section><section class="customer-section"><div class="section-head compact-head"><div><div class="eyebrow">ВАШ АВТОМОБИЛЬ</div><h2>Toyota Camry <span class="car-year">2019</span></h2></div><button class="text-link" data-customer-tab="Автомобиль">Карточка автомобиля ${icons.arrow}</button></div><div class="vehicle-summary"><div class="vehicle-visual"><div class="mini-car"><span></span></div></div><div class="vehicle-data"><span class="plate">А123ВС 77</span><span>2.5 л · Бензин</span><span>Пробег 64 280 км</span></div><div class="vehicle-next"><span class="label">ПОСЛЕДНЕЕ ОБСЛУЖИВАНИЕ</span><strong>Плановое ТО</strong><span>12 июня 2026 · 61 900 км</span></div><div class="vehicle-action"><button class="row-action" data-customer-tab="Автомобиль" aria-label="Автомобиль подробнее">${icons.arrow}</button></div></div></section><section class="customer-section service-summary"><div class="section-head compact-head"><div><div class="eyebrow">ПОСЛЕДНИЙ ЗАКАЗ-НАРЯД</div><h2>Обслуживание завершено</h2></div>${badge('Готово','success')}</div><div class="service-row"><span class="service-date">12<br><small>ИЮН</small></span><div class="service-name"><strong>Плановое техническое обслуживание</strong><span>Заказ-наряд № ЗН-1842 · КОЛЕСОВИК · Центральный</span></div><div class="service-total"><span>ИТОГО</span><strong>${fmt(18400)}</strong></div><button class="row-action" data-customer-tab="История" aria-label="Посмотреть обслуживание">${icons.arrow}</button></div></section><section class="recommendation"><span class="recommendation-icon">✳</span><div><div class="eyebrow">РЕКОМЕНДАЦИЯ СЕРВИСА</div><h3>Проверить состояние тормозной жидкости</h3><p>На следующем плановом обслуживании. Рекомендация не требует срочного визита.</p></div><button class="quiet-button" data-action="ask">Уточнить ${icons.arrow}</button></section><section class="quick-actions"><button data-screen="booking">${icons.calendar}<span><b>Мои записи</b><small>Посмотреть или перенести</small></span>${icons.arrow}</button><button data-action="ask">${icons.chat}<span><b>Задать вопрос</b><small>Мы поможем разобраться</small></span>${icons.arrow}</button></section>`}
function customerHistory(){return `<div class="eyebrow">ВАШ АВТОМОБИЛЬ</div><h1 class="page-title">Toyota Camry <span class="car-year">2019</span></h1><div class="vehicle-summary large-summary"><div class="vehicle-visual"><div class="mini-car"><span></span></div></div><div class="vehicle-data"><span class="plate">А123ВС 77</span><span>2.5 л · Бензин</span><span>Пробег 64 280 км</span></div></div><div class="eyebrow history-eyebrow">ИСТОРИЯ ОБСЛУЖИВАНИЯ</div><h2>Недавние работы</h2><div class="history-list"><div class="history-entry"><span>ИЮН<br><b>12</b></span><div><strong>Плановое техническое обслуживание</strong><small>Заказ-наряд № ЗН-1842 · КОЛЕСОВИК · Центральный</small></div><b>${fmt(18400)}</b>${badge('Завершён','success')}</div><div class="history-entry"><span>ФЕВ<br><b>04</b></span><div><strong>Замена передних тормозных колодок</strong><small>Заказ-наряд № ЗН-1720 · КОЛЕСОВИК · Центральный</small></div><b>${fmt(12600)}</b>${badge('Завершён','success')}</div></div><div class="customer-record-note">Отображаются данные из фиктивного примера. VIN и личные контакты не используются.</div>`}
function customerBookingCard(){return `<button class="back-link mobile-only" data-customer-tab="Главная">← Назад</button><div class="eyebrow">МОИ ЗАПИСИ</div><h1 class="page-title">Запись на обслуживание</h1><div class="booking-tabs"><button class="${bookingMode==='confirmed'?'active':''}" data-booking-mode="confirmed">Подтверждена</button><button class="${bookingMode==='manage'?'active':''}" data-booking-mode="manage">Управление</button></div>${bookingMode==='manage'?`<div class="booking-mode-note"><strong>Управление записью</strong><span>Выберите перенос или отмену. Текущая запись подтверждена.</span></div>`:''}<article class="booking-full"><div class="booking-full-head"><div>${badge(bookingCancelled?'Запись отменена':'Запись подтверждена',bookingCancelled?'danger':'success')}<span class="small-muted">№ ЗП-2048</span></div>${icons.calendar}</div><h2>Замена масла и фильтров</h2><div class="booking-facts"><div><span>ФИЛИАЛ</span><strong>КОЛЕСОВИК · Центральный</strong><small>Москва, ул. Техническая, 12</small></div><div><span>АВТОМОБИЛЬ</span><strong>Toyota Camry</strong><small>2019 · А123ВС 77</small></div><div><span>ДАТА И ВРЕМЯ</span><strong>28 сентября, 15:30</strong><small>Понедельник · местное время филиала</small></div><div><span>СТАТУС</span><strong class="${bookingCancelled?'':'success-text'}">${bookingCancelled?'Отменена':'Подтверждена'}</strong><small>${bookingCancelled?'Вы отменили эту запись':'Запись создана онлайн'}</small></div></div>${bookingCancelled?`<div class="inline-state info-state cancel-result"><span class="state-icon">i</span><div><strong>Запись отменена</strong><p>Если понадобится обслуживание, можно выбрать новое время.</p></div></div>`:`<div class="booking-next"><span class="next-number">ДАЛЕЕ</span><p>Приезжайте за 10 минут. Если планы изменятся, запись можно перенести или отменить.</p></div><div class="booking-ops"><button class="button secondary" data-action="reschedule">Перенести запись</button><button class="button danger-quiet" data-action="cancel-booking">Отменить запись</button></div>`}</article><aside class="booking-note"><span>i</span><p>Доступное время зависит от выбранной услуги, филиала и действующих правил записи.</p></aside>`}
const adminNav=[['Рабочий стол','⌂'],['Записи','▦'],['Заказы','▤'],['Диалоги','◌'],['Смена','◷'],['Клиенты','♙']];
function adminShell(){return `<div class="admin-app"><aside class="admin-sidebar">${topBrand()}<div class="branch-switch"><span class="branch-dot"></span><span><small>ТЕКУЩИЙ ФИЛИАЛ</small><b>Центральный</b></span><span class="chevron">⌄</span></div><nav aria-label="Рабочая навигация">${adminNav.map(([name,icon])=>`<button class="admin-nav-item ${((screen==='order'&&name==='Заказы')||(screen==='shift'&&name==='Смена')||(screen==='dialog'&&name==='Диалоги'))?'active':''}" data-admin-nav="${name}"><span>${icon}</span>${name}${name==='Диалоги'?'<i class="nav-count">3</i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="online-status"><span></span>Система работает</div><div class="admin-user"><span class="avatar admin-avatar">ИС</span><span><b>Ирина Соколова</b><small>Администратор</small></span><button class="more-button" aria-label="Настройки профиля">···</button></div></div></aside><section class="admin-main"><header class="admin-topbar"><div class="crumbs"><span>Рабочая область</span><span>/</span><b>${screen==='order'?'Заказы':screen==='shift'?'Смена':'Диалоги'}</b></div><div class="topbar-right"><span class="date-chip">ПН, 28 СЕН 2026</span><button class="top-icon" aria-label="Уведомления">♧<i></i></button><span class="avatar admin-avatar">ИС</span></div></header><div class="admin-mobile-nav" aria-label="Навигация администратора">${adminNav.filter(x=>['Заказы','Диалоги','Смена'].includes(x[0])).map(([n,i])=>`<button class="${(screen==='order'&&n==='Заказы')||(screen==='shift'&&n==='Смена')||(screen==='dialog'&&n==='Диалоги')?'active':''}" data-admin-nav="${n}"><span>${i}</span>${n}</button>`).join('')}</div><main class="admin-content">${screen==='order'?orderPage():screen==='shift'?shiftPage():dialogPage()}</main></section></div>`}
function orderPage(){const closed=demo==='readonly';return `${stateNotice()}<div class="admin-page-head"><div><div class="eyebrow">ЗАКАЗЫ <span>/</span> ЗАКАЗ-НАРЯД</div><div class="order-title-row"><button class="back-square" aria-label="Назад к заказам">←</button><h1>Заказ <span class="mono-id">№ ЗН-2481</span></h1>${badge(closed?'Закрыт':'В работе',closed?'neutral':'info')}</div></div><div class="head-actions"><button class="button secondary compact">⋯ <span>Действия</span></button><button class="button primary compact" data-action="close-order" ${closed?'disabled':''}>${closed?'Заказ закрыт':'Закрыть заказ'} ${icons.arrow}</button></div></div><div class="order-identity"><div class="order-person"><span class="avatar large-avatar">АМ</span><div><span class="label">КЛИЕНТ</span><strong>Алексей Морозов</strong><small>Клиент с 2022 года · 4 визита</small></div></div><div class="identity-divider"></div><div class="order-vehicle">${icons.car}<div><span class="label">АВТОМОБИЛЬ</span><strong>Toyota Camry · 2019</strong><small>А123ВС 77 · 2.5 л бензин</small></div></div><div class="identity-divider"></div><div class="order-branch"><span class="label">ФИЛИАЛ · ПРИЁМЩИК</span><strong>КОЛЕСОВИК · Центральный</strong><small>Ирина Соколова · 28 сен, 11:42</small></div></div><div class="order-overview"><section class="balance-panel"><div class="balance-heading"><span class="label">К ОПЛАТЕ</span>${badge(closed?'Закрыт · просмотр':'Есть остаток',closed?'neutral':'warning')}</div><div class="balance-amount">${fmt(21600)}</div><div class="balance-breakdown"><span>Итого <b>${fmt(32600)}</b></span><span>Оплачено <b>${fmt(11000)}</b></span></div>${demo==='unknown'?`<div class="unknown-panel"><div class="unknown-symbol">?</div><div><span class="unknown-label">НЕИЗВЕСТНЫЙ ИСХОД</span><strong>Не удалось подтвердить оплату</strong><p>Запрос отправлен, но ответ не получен. Операция не считается ни успешной, ни отклонённой.</p><button class="button secondary compact" data-action="reconcile">Сверить состояние оплаты ${icons.arrow}</button></div></div>`:`<div class="balance-action"><button class="button primary" data-action="payment" ${closed?'disabled':''}>${closed?'Заказ закрыт':'Принять оплату'} <span>${icons.arrow}</span></button><button class="icon-button" aria-label="Другие способы оплаты" data-action="payment">···</button></div>`}</section><section class="next-action-panel"><div class="eyebrow">СЛЕДУЮЩИЙ ШАГ</div><div class="next-action-content"><span class="next-action-check">${closed?'✓':'1'}</span><div><strong>${closed?'Заказ завершён':'Завершить работы и закрыть заказ'}</strong><p>${closed?'Заказ доступен только для просмотра.':'Перед закрытием проверьте состав работ и расчёт.'}</p></div></div>${!closed?`<button class="text-link" data-action="close-order">Перейти к закрытию ${icons.arrow}</button>`:''}</section></div><div class="order-tabs" role="tablist"><button class="${orderTab==='Обзор'?'active':''}" data-order-tab="Обзор">Обзор</button><button class="${orderTab==='Работы и запчасти'?'active':''}" data-order-tab="Работы и запчасти">Работы и запчасти <span>4</span></button><button class="${orderTab==='Оплаты'?'active':''}" data-order-tab="Оплаты">Оплаты <span>2</span></button><button class="${orderTab==='Документы'?'active':''}" data-order-tab="Документы">Документы <span>1</span></button></div><div class="order-body">${orderTab==='Оплаты'?paymentContent():orderTab==='Документы'?documentsContent():orderTab==='Работы и запчасти'?workPartsContent():overviewContent(closed)}</div>`}
function overviewContent(closed){return `<div class="order-main-column"><section class="admin-section"><div class="admin-section-head"><div><div class="eyebrow">ВЫПОЛНЕНО</div><h2>Работы <span class="count">3</span></h2></div><button class="small-action" ${closed?'disabled':''}>+ Добавить</button></div><div class="work-list"><div class="work-row"><span class="work-index">01</span><div><strong>Диагностика ходовой части</strong><small>1 услуга · Алексей Ким</small></div><b>${fmt(5400)}</b></div><div class="work-row"><span class="work-index">02</span><div><strong>Замена передних тормозных колодок</strong><small>1 услуга · Алексей Ким</small></div><b>${fmt(6800)}</b></div><div class="work-row"><span class="work-index">03</span><div><strong>Замена масла и фильтра</strong><small>1 услуга · Сергей Павлов</small></div><b>${fmt(3200)}</b></div></div></section><section class="admin-section"><div class="admin-section-head"><div><div class="eyebrow">УСТАНОВЛЕНО</div><h2>Запчасти <span class="count">2</span></h2></div><button class="small-action" ${closed?'disabled':''}>+ Добавить</button></div><div class="compact-lines"><div><span>Колодки тормозные передние · комплект</span><small>1 × ${fmt(18400)}</small><b>${fmt(18400)}</b></div><div><span>Фильтр масляный</span><small>1 × ${fmt(800)}</small><b>${fmt(800)}</b></div></div></section><section class="admin-section recommendations-section"><div class="admin-section-head"><div><div class="eyebrow">ДЛЯ СЛЕДУЮЩЕГО ВИЗИТА</div><h2>Рекомендации</h2></div><span class="recommendation-count">2</span></div><div class="recommendation-item"><span class="rec-dot"></span><div><strong>Проверить тормозную жидкость</strong><small>При следующем плановом обслуживании</small></div><button class="small-action" ${closed?'disabled':''}>Изменить</button></div><div class="recommendation-item"><span class="rec-dot neutral-dot"></span><div><strong>Контроль состояния аккумулятора</strong><small>В течение ближайших 3 месяцев</small></div><button class="small-action" ${closed?'disabled':''}>Изменить</button></div></section></div><aside class="order-side-column"><section class="totals-box"><div class="eyebrow">РАСЧЁТ ЗАКАЗА</div><div class="total-line"><span>Работы</span><b>${fmt(15400)}</b></div><div class="total-line"><span>Запчасти</span><b>${fmt(19200)}</b></div><div class="total-line discount-line"><span>Скидка · постоянный клиент</span><b>− ${fmt(2000)}</b></div><div class="total-separator"></div><div class="grand-total"><span>Итого</span><b>${fmt(32600)}</b></div><div class="payments-small"><span>Оплаты · 2 операции</span><b>− ${fmt(11000)}</b></div><div class="remaining-line"><span>Остаток</span><b>${fmt(21600)}</b></div><button class="text-link" data-order-tab="Оплаты">История оплат ${icons.arrow}</button></section><section class="executor-box"><div class="eyebrow">ИСПОЛНИТЕЛИ</div><div class="executor-row"><span class="avatar small-avatar">АК</span><span><b>Алексей Ким</b><small>Мастер · 2 работы</small></span><span class="executor-share">2</span></div><div class="executor-row"><span class="avatar small-avatar alt-avatar">СП</span><span><b>Сергей Павлов</b><small>Мастер · 1 работа</small></span><span class="executor-share">1</span></div></section><button class="details-disclosure" data-action="details-toggle">Служебные сведения <span>＋</span></button></aside>`}
function paymentContent(){return `<div class="payment-ledger"><div class="admin-section-head"><div><div class="eyebrow">ФИНАНСЫ · ЗАКАЗ ЗН-2481</div><h2>История оплат</h2></div><button class="button primary compact" data-action="payment">Принять оплату ${icons.arrow}</button></div>${demo==='unknown'?`<div class="unknown-panel ledger-unknown"><div class="unknown-symbol">?</div><div><span class="unknown-label">НЕИЗВЕСТНЫЙ ИСХОД · ОПЕРАЦИЯ 03</span><strong>Сверьте состояние перед любым следующим действием</strong><p>Мы отправили запрос на оплату ${fmt(5000)}, но не получили подтверждение. Не отправляйте его повторно вслепую.</p><button class="button secondary compact" data-action="reconcile">Обновить историю оплат ${icons.arrow}</button></div></div>`:''}<div class="ledger-table"><div class="ledger-header"><span>ОПЕРАЦИЯ</span><span>ДАТА</span><span>СПОСОБ</span><span>СУММА</span><span>СОСТОЯНИЕ</span></div><div class="ledger-row"><strong>Оплата № ОП-0314</strong><span>28 сен, 12:18</span><span>Банковская карта</span><b>${fmt(8000)}</b>${badge('Проведена','success')}</div><div class="ledger-row"><strong>Оплата № ОП-0299</strong><span>28 сен, 11:49</span><span>Наличные</span><b>${fmt(3000)}</b>${badge('Проведена','success')}</div></div><div class="ledger-total"><span>Всего оплачено</span><b>${fmt(11000)}</b><span>Остаток к оплате</span><b>${fmt(21600)}</b></div></div>`}
